+const navToggle = document.querySelector(".nav-toggle");
+const navMenu = document.querySelector(".nav-menu");
+const filterButtons = document.querySelectorAll(".filter-button");
+const productCards = document.querySelectorAll(".product-card");
+const addButtons = document.querySelectorAll(".add-button, .icon-button");
+const newsletterForm = document.querySelector(".newsletter-form");
+const formMessage = document.querySelector(".form-message");
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navMenu.classList.toggle("open");
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+});
+
+navMenu.addEventListener("click", (event) => {
+  if (event.target.matches("a")) {
+    navMenu.classList.remove("open");
+    navToggle.setAttribute("aria-expanded", "false");
+  }
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const filter = button.dataset.filter;
+
+    filterButtons.forEach((item) => item.classList.remove("active"));
+    button.classList.add("active");
+
+    productCards.forEach((card) => {
+      const shouldShow = filter === "all" || card.dataset.category === filter;
+      card.classList.toggle("hidden", !shouldShow);
+    });
+  });
+});
+
+addButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const originalText = button.textContent;
+    button.textContent = "Added";
+    button.disabled = true;
+
+    window.setTimeout(() => {
+      button.textContent = originalText;
+      button.disabled = false;
+    }, 1200);
+  });
+});
+
+const dealEndsAt = Date.now() + 8 * 60 * 60 * 1000 + 45 * 60 * 1000;
+const hoursElement = document.querySelector("#hours");
+const minutesElement = document.querySelector("#minutes");
+const secondsElement = document.querySelector("#seconds");
+
+function updateCountdown() {
+  const remaining = Math.max(0, dealEndsAt - Date.now());
+  const totalSeconds = Math.floor(remaining / 1000);
+  const hours = Math.floor(totalSeconds / 3600);
+  const minutes = Math.floor((totalSeconds % 3600) / 60);
+  const seconds = totalSeconds % 60;
+
+  hoursElement.textContent = String(hours).padStart(2, "0");
+  minutesElement.textContent = String(minutes).padStart(2, "0");
+  secondsElement.textContent = String(seconds).padStart(2, "0");
+}
+
+updateCountdown();
+window.setInterval(updateCountdown, 1000);
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const email = new FormData(newsletterForm).get("email") || document.querySelector("#email").value;
+  formMessage.textContent = `Thanks. Insider access is reserved for ${email}.`;
+  newsletterForm.reset();
+});
